//! Yew: server-rendered with `LocalServerRenderer` (hydratable), hydrated with
//! `Renderer::hydrate`.

use bench_common::COUNTER_START;
use yew::prelude::*;

/// Library name, which names the files generated by wasm-bindgen.
pub const LIB: &str = "counter_yew";

/// A button that increments the number next to it.
#[function_component]
pub fn App() -> Html {
    let count = use_state(|| COUNTER_START);
    // Effects run once the (hydrated) render is committed (never on the server).
    use_effect_with((), |_| bench_common::mark("data-ready"));
    let onclick = {
        let count = count.clone();
        Callback::from(move |_| count.set(*count + 1))
    };
    html! {
        <>
            <button id="inc" {onclick}>{ "+1" }</button>
            <span id="count">{ *count }</span>
        </>
    }
}

/// The server HTML.
#[cfg(not(target_arch = "wasm32"))]
pub fn page() -> String {
    let runtime = tokio::runtime::Builder::new_current_thread()
        .build()
        .expect("tokio runtime");
    let body = runtime.block_on(yew::LocalServerRenderer::<App>::new().render());
    bench_common::counter_page(LIB, &body)
}

#[cfg(target_arch = "wasm32")]
#[wasm_bindgen::prelude::wasm_bindgen(start)]
pub fn start() {
    bench_common::mark("data-start");
    // Asynchronous: hydrates on Yew's scheduler, then runs the effect above.
    yew::Renderer::<App>::new().hydrate();
}
